const loader=document.getElementById('loader');window.addEventListener('load',()=>setTimeout(()=>loader.remove(),900));const menu=document.querySelector('.menu-btn');menu.addEventListener('click',()=>document.body.classList.toggle('menu-open'));document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>document.body.classList.remove('menu-open')));const top=document.getElementById('top');window.addEventListener('scroll',()=>top.classList.toggle('show',scrollY>500));top.onclick=()=>scrollTo({top:0,behavior:'smooth'});const form=document.getElementById('appointmentForm');const msg=document.getElementById('formMessage');form.addEventListener('submit',e=>{e.preventDefault();if(!form.checkValidity()){form.reportValidity();return}const d=new FormData(form);const text=['Hi BrightSmile! I would like to request an appointment.','Name: '+d.get('name'),'Phone: '+d.get('phone'),'Email: '+(d.get('email')||'Not provided'),'Service: '+d.get('service'),'Preferred date: '+d.get('date'),'Preferred time: '+d.get('time'),'Message: '+(d.get('message')||'None')].join('\n');msg.hidden=false;msg.textContent='Booking request prepared. Opening WhatsApp so the clinic can confirm your slot.';window.open('https://wa.me/919840012345?text='+encodeURIComponent(text),'_blank');});const date=document.querySelector('input[type=date]');date.min=new Date().toISOString().split('T')[0];